package app.loveu;public class TapGestureTest {static void check(boolean b){if(!b)throw new AssertionError();}public static void main(String[] args){TapGesture g=new TapGesture(8);check(!g.finish(10,10));g.start(10,10);check(g.finish(14,14));check(!g.finish(14,14));g.start(10,10);g.move(30,10);g.move(10,10);check(!g.finish(10,10));g.start(10,10);g.cancel();check(!g.finish(10,10));g.start(10,10);check(!g.finish(10,19));System.out.println("TapGestureTest passed");}}
